\set ON_ERROR_STOP on
begin;
insert into auth.users(id,email) values ('91000000-0000-0000-0000-000000000001','grillad-owner@test.invalid'),('91000000-0000-0000-0000-000000000002','grillad-seller@test.invalid');
insert into auth.sessions(id,user_id) values ('91000000-0000-0000-0000-000000000011','91000000-0000-0000-0000-000000000001'),('91000000-0000-0000-0000-000000000012','91000000-0000-0000-0000-000000000002');
insert into famille_core.organizations(id,legal_name,organization_type,status) values('92000000-0000-0000-0000-000000000001','Test GrillaD','retail','active');
update famille_core.applications set status='active' where code in ('grillad','zipple');
insert into famille_core.organization_apps(organization_id,app_id,status) select '92000000-0000-0000-0000-000000000001',id,'active' from famille_core.applications where code='grillad';
insert into famille_core.locations(id,organization_id,name) values ('93000000-0000-0000-0000-000000000001','92000000-0000-0000-0000-000000000001','A'),('93000000-0000-0000-0000-000000000002','92000000-0000-0000-0000-000000000001','B');
insert into famille_core.locations(id,organization_id,name) values ('93000000-0000-0000-0000-000000000003','92000000-0000-0000-0000-000000000001','Other app');
insert into grillad_private.enabled_sites(org,site) values ('92000000-0000-0000-0000-000000000001','93000000-0000-0000-0000-000000000001'),('92000000-0000-0000-0000-000000000001','93000000-0000-0000-0000-000000000002');
insert into famille_core.client_app_access(user_id,app_id,status) select u.id,a.id,'granted' from auth.users u cross join famille_core.applications a where a.code='grillad';
insert into famille_core.memberships(user_id,organization_id,app_id,status) select u.id,'92000000-0000-0000-0000-000000000001',a.id,'active' from auth.users u cross join famille_core.applications a where a.code='grillad';
insert into famille_core.role_assignments(membership_id,app_id,organization_id,role_code,location_id) select id,app_id,organization_id,case when user_id='91000000-0000-0000-0000-000000000001' then 'owner' else 'seller' end,case when user_id='91000000-0000-0000-0000-000000000002' then '93000000-0000-0000-0000-000000000001'::uuid else null end from famille_core.memberships;
insert into famille_core.subscriptions(organization_id,app_id,plan_id,status,starts_at,ends_at) select '92000000-0000-0000-0000-000000000001',app_id,id,'active',now()-interval '1 day',now()+interval '1 day' from famille_core.plans where code='grillad_premium_month';
select set_config('grillad.test.app',(select id::text from famille_core.applications where code='grillad'),true);
select set_config('grillad.test.other',(select id::text from famille_core.applications where code='zipple'),true);
set role authenticated;
select set_config('request.jwt.claim.sub','91000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',jsonb_build_object('session_id','91000000-0000-0000-0000-000000000011','app_metadata',jsonb_build_object('active_app_id',current_setting('grillad.test.app')))::text,true);
do $$
declare o uuid:='92000000-0000-0000-0000-000000000001';a uuid:='93000000-0000-0000-0000-000000000001';b uuid:='93000000-0000-0000-0000-000000000002';i uuid:='94000000-0000-0000-0000-000000000001';e uuid:='94000000-0000-0000-0000-000000000002';s uuid:='94000000-0000-0000-0000-000000000003';v jsonb;basket uuid:=gen_random_uuid();j uuid:=gen_random_uuid();payload jsonb;adj uuid:=gen_random_uuid();ex uuid:=gen_random_uuid();ce uuid:=gen_random_uuid();day date:=(now() at time zone 'Africa/Douala')::date;
begin
 if jsonb_array_length(public.grillad_workspace())<>2 then raise exception 'workspace owner';end if;
 v:=public.grillad_action(o,a,e,'create_site','{"name":"C","reason":"Extension réseau"}');
 if v->>'id'<>e::text or public.grillad_action(o,a,e,'create_site','{"name":"C","reason":"Extension réseau"}')<>v or jsonb_array_length(public.grillad_workspace())<>3 then raise exception 'create site or replay';end if;
 e:=gen_random_uuid();
 begin perform public.grillad_snapshot(o,'93000000-0000-0000-0000-000000000003',day,day);raise exception 'expected non GRILLAD site denial';exception when insufficient_privilege then null;end;
 perform public.grillad_action(o,a,i,'add_item','{"name":"Poulet","family":"Poulet","price":1000,"cost":400}');
 perform public.grillad_action(o,a,e,'prepare',jsonb_build_object('item',i,'qty',5));
 perform public.grillad_action(o,a,gen_random_uuid(),'open_cash','{"opening":100}');
 begin perform public.grillad_action(o,a,gen_random_uuid(),'sell',jsonb_build_object('item',i,'qty',1,'price',1000,'received',900));raise exception 'cash mismatch';exception when invalid_parameter_value then null;end;
 v:=public.grillad_action(o,a,s,'sell',jsonb_build_object('item',i,'qty',2,'price',1000,'received',2000));if (v->>'total')::int<>2000 then raise exception 'total';end if;
 if public.grillad_action(o,a,s,'sell',jsonb_build_object('item',i,'qty',2,'price',1000,'received',2000))<>v then raise exception 'replay';end if;
 begin perform public.grillad_action(o,a,s,'sell',jsonb_build_object('item',i,'qty',1));raise exception 'expected replay conflict';exception when invalid_parameter_value then null;end;
 begin perform public.grillad_action(o,a,gen_random_uuid(),'sell',jsonb_build_object('item',i,'qty',4,'price',1000,'received',4000));raise exception 'expected stock rejection';exception when invalid_parameter_value then null;end;
 begin perform public.grillad_action(o,b,gen_random_uuid(),'prepare',jsonb_build_object('item',i,'qty',1));raise exception 'expected cross site rejection';exception when insufficient_privilege then null;end;
 v:=public.grillad_action(o,a,gen_random_uuid(),'change_price',jsonb_build_object('item',i,'price',1200,'reason','Test'));if (v->>'old_price')::int<>1000 or (v->>'new_price')::int<>1200 then raise exception 'price history';end if;
 perform public.grillad_action(o,a,gen_random_uuid(),'expense','{"label":"Bois","value":200}');
 perform public.grillad_action(o,a,ex,'expense','{"label":"Erreur","value":100}');
 v:=public.grillad_action(o,a,ce,'cancel_expense',jsonb_build_object('expense',ex,'reason','Saisie erronée'));
 if public.grillad_action(o,a,ce,'cancel_expense',jsonb_build_object('expense',ex,'reason','Saisie erronée'))<>v then raise exception 'expense replay';end if;
 begin perform public.grillad_action(o,a,gen_random_uuid(),'cancel_expense',jsonb_build_object('expense',ex,'reason','Duplicata'));raise exception 'expense duplicate reversal';exception when invalid_parameter_value then null;end;
 v:=public.grillad_action(o,a,adj,'adjust_stock',jsonb_build_object('item',i,'delta',-1,'reason','Perte'));
 if (v->>'remaining')::int<>2 or public.grillad_action(o,a,adj,'adjust_stock',jsonb_build_object('item',i,'delta',-1,'reason','Perte'))<>v then raise exception 'adjustment replay';end if;
 begin perform public.grillad_action(o,a,gen_random_uuid(),'adjust_stock',jsonb_build_object('item',i,'delta',-3,'reason','Perte'));raise exception 'negative stock adjustment';exception when invalid_parameter_value then null;end;
 perform public.grillad_action(o,a,gen_random_uuid(),'adjust_stock',jsonb_build_object('item',i,'delta',1,'reason','Correction'));

 perform public.grillad_action(o,a,gen_random_uuid(),'dimension_target',jsonb_build_object('day',day,'kind','family','subject','Poulet','amount',5000,'reason','Objectif'));
 perform public.grillad_action(o,a,gen_random_uuid(),'dimension_target',jsonb_build_object('day',day,'kind','item','subject',i,'amount',4000,'reason','Objectif'));
 perform public.grillad_action(o,a,gen_random_uuid(),'dimension_target',jsonb_build_object('day',day,'kind','seller','subject','91000000-0000-0000-0000-000000000002','amount',3000,'reason','Objectif'));
 begin perform public.grillad_action(o,b,gen_random_uuid(),'dimension_target',jsonb_build_object('day',day,'kind','item','subject',i,'amount',1,'reason','Test'));raise exception 'target scope';exception when insufficient_privilege then null;end;
 v:=public.grillad_snapshot(o,a,day,day);
 if jsonb_array_length(v->'dimension_targets')<>3 or not exists(select 1 from jsonb_array_elements(v->'dimension_targets') x where x->>'kind'='family' and (x->>'actual')::int=2000) or not exists(select 1 from jsonb_array_elements(v->'dimension_targets') x where x->>'kind'='seller' and (x->>'actual')::int=0) then raise exception 'dimension targets';end if;
 v:=public.grillad_snapshot(o,a,day,day);if (v#>>'{finance,ca}')::int<>2000 or (v#>>'{finance,charges}')::int<>200 or jsonb_array_length(v->'expenses')<>2 or jsonb_array_length(v->'stock_adjustments')<>2 or (v->'items'->0->>'price')::int<>1200 then raise exception 'finance';end if;
 perform public.grillad_action(o,a,j,'add_item','{"name":"Porc","family":"Porc","price":800,"cost":300}');
 perform public.grillad_action(o,a,gen_random_uuid(),'prepare',jsonb_build_object('item',j,'qty',4));
 payload:=jsonb_build_object('received',2800,'lines',jsonb_build_array(jsonb_build_object('item',i,'qty',1,'price',1200),jsonb_build_object('item',j,'qty',2,'price',800)));
 v:=public.grillad_action(o,a,basket,'sell_basket',payload);
 if (v->>'total')::int<>2800 or public.grillad_action(o,a,basket,'sell_basket',payload)<>v then raise exception 'basket total or replay';end if;
 v:=public.grillad_receipt(o,a,basket);if (v->>'total')::int<>2800 or jsonb_array_length(v->'lines')<>2 or (v->>'cancelled')::boolean then raise exception 'receipt basket';end if;
 v:=public.grillad_receipt(o,a,s);if (v->'lines'->0->>'price')::int<>1000 then raise exception 'receipt historical price';end if;
 begin perform public.grillad_receipt(o,b,s);raise exception 'receipt cross site';exception when insufficient_privilege then null;end;
 v:=public.grillad_snapshot(o,a,day,day);
 if (v#>>'{finance,ca}')::int<>4800 or (v#>>'{finance,encaissements}')::int<>4800 or jsonb_array_length(v->'cash_receipts')<>2 or (v#>>'{finance,sales_count}')::int<>2 then raise exception 'basket counted as multiple sales';end if;
 begin perform public.grillad_action(o,a,gen_random_uuid(),'sell_basket',jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('item',i,'qty',1,'price',1200),jsonb_build_object('item',j,'qty',100,'price',800))));raise exception 'expected basket rollback';exception when invalid_parameter_value then null;end;
 v:=public.grillad_snapshot(o,a,day,day);if (v#>>'{finance,ca}')::int<>4800 then raise exception 'partial basket';end if;
 perform public.grillad_action(o,a,gen_random_uuid(),'cancel_basket',jsonb_build_object('sale',basket,'reason','Test cancellation'));
 v:=public.grillad_receipt(o,a,basket);if not (v->>'cancelled')::boolean or (v->>'net_total')::int<>0 then raise exception 'cancelled receipt';end if;
 v:=public.grillad_snapshot(o,a,day,day);if (v#>>'{finance,ca}')::int<>2000 or (v#>>'{finance,encaissements}')::int<>2000 or (v#>>'{finance,sales_count}')::int<>1 then raise exception 'basket cancellation';end if;
 begin perform public.grillad_action(o,a,gen_random_uuid(),'close_cash','{"counted":1800}');raise exception 'expected reason';exception when invalid_parameter_value then null;end;
 v:=public.grillad_action(o,a,gen_random_uuid(),'close_cash','{"counted":1900}');if (v->>'difference')::int<>0 then raise exception 'cash';end if;
 v:=public.grillad_snapshot(o,a,day,day);if jsonb_array_length(v->'cash_history')<>1 or (v->'cash_history'->0->>'counted')::int<>1900 then raise exception 'cash history';end if;
 v:=public.grillad_action(o,a,gen_random_uuid(),'change_cost',jsonb_build_object('item',i,'cost',450,'reason','New unit cost'));if (v->>'old_cost')::int<>400 or (v->>'new_cost')::int<>450 then raise exception 'cost edit';end if;
 v:=public.grillad_snapshot(o,a,day,day);if (v#>>'{finance,cost}')::int<>800 then raise exception 'historical cost must not change';end if;
 v:=public.grillad_action(o,a,gen_random_uuid(),'set_cost_composition',jsonb_build_object('item',i,'reason','Estimation','components',jsonb_build_array(jsonb_build_object('label','Viande','amount',400),jsonb_build_object('label','Charbon','amount',50))));
 if (v->>'new_cost')::int<>450 or v->>'quality'<>'estimated' then raise exception 'complete composition';end if;
 v:=public.grillad_action(o,a,gen_random_uuid(),'set_cost_composition',jsonb_build_object('item',i,'reason','Lot de production','batch_units',3,'components',jsonb_build_array(jsonb_build_object('label','Viande','amount',1000),jsonb_build_object('label','Charbon','amount',100))));
 if (v->>'new_cost')::int<>367 or (v->>'batch_total')::int<>1100 or (v->>'batch_units')::int<>3 then raise exception 'batch cost round up';end if;
 begin perform public.grillad_action(o,a,gen_random_uuid(),'set_cost_composition',jsonb_build_object('item',i,'reason','Test','batch_units',0,'components',jsonb_build_array(jsonb_build_object('label','Viande','amount',1000))));raise exception 'zero yield accepted';exception when invalid_parameter_value then null;end;
 v:=public.grillad_action(o,a,gen_random_uuid(),'set_cost_composition',jsonb_build_object('item',i,'reason','Estimation','components',jsonb_build_array(jsonb_build_object('label','Viande','amount',400),jsonb_build_object('label','Charbon','amount',null))));
 if v->'new_cost'<>'null'::jsonb or v->>'quality'<>'incomplete' then raise exception 'incomplete composition';end if;
 v:=public.grillad_snapshot(o,a,day,day);if (v#>>'{finance,cost}')::int<>800 then raise exception 'composition rewrote history';end if;
 begin perform public.grillad_action(o,a,gen_random_uuid(),'set_cost_composition',jsonb_build_object('item',i,'reason','Test','components',jsonb_build_array(jsonb_build_object('label','Viande','amount',-1))));raise exception 'negative component';exception when invalid_parameter_value then null;end;

 begin perform public.grillad_action(o,a,gen_random_uuid(),'set_item_active',jsonb_build_object('item',i,'active',false,'reason','Test'));raise exception 'deactivation with stock';exception when invalid_parameter_value then null;end;
 j:=gen_random_uuid();perform public.grillad_action(o,a,j,'add_item','{"name":"Archive","family":"Omelettes","price":500}');perform public.grillad_action(o,a,gen_random_uuid(),'set_item_active',jsonb_build_object('item',j,'active',false,'reason','Test'));v:=public.grillad_snapshot(o,a,day,day);if jsonb_array_length(v->'inactive_items')<>1 then raise exception 'inactive item history';end if;
 perform public.grillad_action(o,a,gen_random_uuid(),'set_item_active',jsonb_build_object('item',j,'active',true,'reason','Test'));v:=public.grillad_snapshot(o,a,day,day);if jsonb_array_length(v->'inactive_items')<>0 then raise exception 'reactivation';end if;
end $$;
select set_config('request.jwt.claim.sub','91000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims',jsonb_build_object('session_id','91000000-0000-0000-0000-000000000012','app_metadata',jsonb_build_object('active_app_id',current_setting('grillad.test.app')))::text,true);
do $$
declare o uuid:='92000000-0000-0000-0000-000000000001';a uuid:='93000000-0000-0000-0000-000000000001';b uuid:='93000000-0000-0000-0000-000000000002';day date:=(now() at time zone 'Africa/Douala')::date;v jsonb;
begin
 if jsonb_array_length(public.grillad_workspace())<>1 then raise exception 'workspace seller';end if;
 v:=public.grillad_snapshot(o,a,day,day);
 if jsonb_array_length(v->'cash_receipts')<>0 then raise exception 'seller cash receipt leak';end if;
 if jsonb_array_length(v->'dimension_targets')<>0 then raise exception 'seller target leak';end if;
 if v->'finance'<>'null'::jsonb or jsonb_array_length(v->'sales')<>0 or (v->'items'->0)?'cost' or jsonb_array_length(v->'cash_history')<>0 or jsonb_array_length(v->'inactive_items')<>0 then raise exception 'seller leak';end if;
 begin perform public.grillad_snapshot(o,b,day,day);raise exception 'expected site denial';exception when insufficient_privilege then null;end;
 begin perform public.grillad_receipt(o,a,'94000000-0000-0000-0000-000000000003');raise exception 'receipt other seller';exception when insufficient_privilege then null;end;
 begin perform public.grillad_action(o,a,gen_random_uuid(),'open_cash','{"opening":0}');raise exception 'expected role denial';exception when insufficient_privilege then null;end;
 begin perform public.grillad_action(o,a,gen_random_uuid(),'adjust_stock',jsonb_build_object('item','94000000-0000-0000-0000-000000000001','delta',1,'reason','Test'));raise exception 'seller adjustment allowed';exception when insufficient_privilege then null;end;
 begin perform count(*) from grillad_private.items;raise exception 'expected table denial';exception when insufficient_privilege then null;end;
end $$;
select set_config('request.jwt.claims',jsonb_build_object('session_id','91000000-0000-0000-0000-000000000012','app_metadata',jsonb_build_object('active_app_id',current_setting('grillad.test.other')))::text,true);
do $$begin
 begin perform public.grillad_snapshot('92000000-0000-0000-0000-000000000001','93000000-0000-0000-0000-000000000001',current_date,current_date);raise exception 'expected app denial';exception when insufficient_privilege then null;end;
end $$;
reset role;
update famille_core.subscriptions set plan_id=(select id from famille_core.plans where code='grillad_access_month');
set role authenticated;
select set_config('request.jwt.claim.sub','91000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',jsonb_build_object('session_id','91000000-0000-0000-0000-000000000011','app_metadata',jsonb_build_object('active_app_id',current_setting('grillad.test.app')))::text,true);
do $$begin if jsonb_array_length(public.grillad_workspace())<>0 then raise exception 'ACCESS must reject two enabled sites';end if;end $$;
reset role;
update grillad_private.enabled_sites set enabled=false where org='92000000-0000-0000-0000-000000000001' and site<>'93000000-0000-0000-0000-000000000001';
set role authenticated;
do $$begin if jsonb_array_length(public.grillad_workspace())<>1 then raise exception 'ACCESS must allow only explicit site';end if;
 begin perform public.grillad_action('92000000-0000-0000-0000-000000000001','93000000-0000-0000-0000-000000000001',gen_random_uuid(),'create_site','{"name":"D","reason":"Test"}');raise exception 'ACCESS second site';exception when insufficient_privilege then null;end;
end $$;
reset role;
delete from auth.sessions where id='91000000-0000-0000-0000-000000000012';
set role authenticated;
select set_config('request.jwt.claim.sub','91000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims',jsonb_build_object('session_id','91000000-0000-0000-0000-000000000012','app_metadata',jsonb_build_object('active_app_id',current_setting('grillad.test.app')))::text,true);
do $$begin
 begin perform public.grillad_snapshot('92000000-0000-0000-0000-000000000001','93000000-0000-0000-0000-000000000001',current_date,current_date);raise exception 'expected session denial';exception when insufficient_privilege then null;end;
end $$;
reset role;
rollback;
